const LIB = new URL("./page-themes-lib/", import.meta.url)

// an SVG drawing (its parts marked with data-role) in a theme's own way: the theme's module and the hook, loaded once
async function dress(t, svg) {
  const [hook, mod] = await Promise.all([import(new URL("themeHook.js", LIB).href), import(new URL(t.file, LIB).href)])
  const full = Object.values(mod).find(v => v && typeof v === "object" && v.id === t.id && v.roles)
  if (!full) throw new Error("no theme " + t.id + " in " + t.file)
  return hook.themeNode(svg, { id: "timeline" }, full)
}

export default {
  id: "timeline-page-themes",
  title: "Page themes",
  description: "45 page themes (水墨, 古舆图, Blueprint, Middle-earth, youdata …): the timeline's paper, inks and lettering, and an SVG export in the theme's own drawing.",
  setup(core) {
    if (!core.timeline) { console.warn("timeline-page-themes: not a timeline (no core.timeline)"); return }
    const off = core.timeline.addThemes(THEMES.map(t => ({ ...t, dress: svg => dress(t, svg) })))
    return () => off()
  },
}
